import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const ADJUSTMENT_TYPES = ['추경예산', '전용', '이용', '예비비'];
const REDUCTION_TYPES = ['전용', '이용'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

// 가정: 집행액·예산잔액의 출처 테이블이 schema.sql에 없다.
// 집행액 = 전용·이용으로 신청·마감·승인된 감액 합계, 예산잔액 = 프로젝트 금액 - 집행액 으로 정한다.
const EXECUTED_SQL = `
  COALESCE((
    SELECT SUM(a.amount)
    FROM budget_adjustment a
    WHERE a.budget_item_id = i.budget_item_id
      AND (CAST(:projectId AS bigint) IS NULL OR a.project_id = CAST(:projectId AS bigint))
      AND a.adjustment_type IN ('전용', '이용')
      AND a.status IN ('신청', '마감', '승인')
  ), 0)`;
const BASE_SQL = `
  COALESCE((
    SELECT SUM(p.amount)
    FROM project p
    WHERE CAST(:projectId AS bigint) IS NULL OR p.project_id = CAST(:projectId AS bigint)
  ), 0)`;

type Db = {
  query: (sql: string, params: Record<string, unknown>) => Promise<any[]>;
};

function isNumeric(v: unknown): boolean {
  if (typeof v === 'number') return Number.isFinite(v);
  if (typeof v === 'string') return /^-?\d+(\.\d+)?$/.test(v.trim());
  return false;
}

function isId(v: unknown): boolean {
  if (typeof v === 'number') return Number.isInteger(v) && v > 0;
  if (typeof v === 'string') return /^\d+$/.test(v.trim()) && Number(v) > 0;
  return false;
}

function optionalId(v: unknown): string | null {
  if (v === undefined || v === null || v === '') return null;
  if (!isId(v)) {
    throw new ApiError(400, 'VALIDATION_FAILED', 'ID는 양의 정수여야 합니다.');
  }
  return String(v).trim();
}

function pathId(req: Request): string {
  const id = req.params['budgetAdjustmentId'];
  if (!isId(id)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '예산조정 ID가 올바르지 않습니다.');
  }
  return id;
}

async function loadAdjustment(db: Db, id: string) {
  const rows = await db.query(
    `SELECT status AS "status", approval_document_id AS "approvalDocumentId"
     FROM budget_adjustment
     WHERE budget_adjustment_id = CAST(:id AS bigint)`,
    { id },
  );
  if (rows.length === 0) {
    throw new ApiError(404, 'BUDGET_ADJUSTMENT_NOT_FOUND', '대상 예산조정이 없습니다.');
  }
  return rows[0];
}

@Controller('api/v1')
export class FnSfr00304Controller {
  @Get('/budget-items/execution-balances')
  async listBudgetItemBalances(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const budgetItemId = optionalId(q['budgetItemId']);
    const projectId = optionalId(q['projectId']);
    const rawPage = q['page'];
    const rawSize = q['size'];
    const page = rawPage === undefined || rawPage === '' ? 0 : Number(rawPage);
    const size = rawSize === undefined || rawSize === '' ? DEFAULT_SIZE : Number(rawSize);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1 || size > MAX_SIZE) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 쪽 크기가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const where = `WHERE (CAST(:budgetItemId AS bigint) IS NULL OR i.budget_item_id = CAST(:budgetItemId AS bigint))`;
      const items = await db.query(
        `SELECT i.budget_item_id AS "budgetItemId",
                i.item_name AS "itemName",
                ${EXECUTED_SQL} AS "executedAmount",
                ${BASE_SQL} - ${EXECUTED_SQL} AS "balanceAmount"
         FROM budget_item i
         ${where}
         ORDER BY i.budget_item_id
         LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)`,
        { budgetItemId, projectId, size, offset: page * size },
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total" FROM budget_item i ${where}`,
        { budgetItemId },
      );
      return { items, page, size, total: Number(counts[0].total) };
    });
  }

  @Post('/budget-adjustments')
  @HttpCode(200)
  async createBudgetAdjustment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const adjustmentType = data['adjustmentType'];
    const budgetItemId = data['budgetItemId'];
    const projectId = data['projectId'];
    const amount = data['amount'];
    const reason = data['reason'];
    if (typeof adjustmentType !== 'string' || !ADJUSTMENT_TYPES.includes(adjustmentType)) {
      throw new ApiError(422, 'BUDGET_ADJUSTMENT_INVALID', '예산조정 구분을 선택해 주세요.');
    }
    if (!isId(budgetItemId)) {
      throw new ApiError(422, 'BUDGET_ADJUSTMENT_INVALID', '대상 예산과목을 선택해 주세요.');
    }
    if (!isId(projectId)) {
      throw new ApiError(422, 'BUDGET_ADJUSTMENT_INVALID', '프로젝트를 선택해 주세요.');
    }
    if (!isNumeric(amount) || Number(amount) <= 0) {
      throw new ApiError(422, 'BUDGET_ADJUSTMENT_INVALID', '조정 금액은 0보다 큰 숫자여야 합니다.');
    }
    if (reason !== undefined && reason !== null && typeof reason !== 'string') {
      throw new ApiError(422, 'BUDGET_ADJUSTMENT_INVALID', '조정 사유는 글자여야 합니다.');
    }
    const itemId = String(budgetItemId).trim();
    const projId = String(projectId).trim();
    return transaction(async (db) => {
      const items = await db.query(
        `SELECT budget_item_id FROM budget_item WHERE budget_item_id = CAST(:itemId AS bigint)`,
        { itemId },
      );
      if (items.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '대상 예산과목이 없습니다.');
      }
      const projects = await db.query(
        `SELECT project_id FROM project WHERE project_id = CAST(:projId AS bigint)`,
        { projId },
      );
      if (projects.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '프로젝트가 없습니다.');
      }
      if (REDUCTION_TYPES.includes(adjustmentType)) {
        const rows = await db.query(
          `SELECT ${BASE_SQL} - ${EXECUTED_SQL} AS "balanceAmount"
           FROM budget_item i
           WHERE i.budget_item_id = CAST(:itemId AS bigint)`,
          { itemId, projectId: projId },
        );
        const balance = Number(rows[0].balanceAmount);
        if (Number(amount) > balance) {
          throw new ApiError(422, 'BUDGET_BALANCE_INSUFFICIENT', '감액 금액이 예산잔액을 초과합니다.');
        }
      }
      const created = await db.query(
        `INSERT INTO budget_adjustment
           (budget_item_id, project_id, requester_id, adjustment_type, amount, reason, status, created_at, updated_at)
         VALUES
           (CAST(:itemId AS bigint), CAST(:projId AS bigint), CAST(:userId AS bigint), :adjustmentType,
            CAST(:amount AS numeric), :reason, '신청', now(), now())
         RETURNING budget_adjustment_id AS "budgetAdjustmentId", status AS "status"`,
        {
          itemId,
          projId,
          userId: user.id,
          adjustmentType,
          amount: String(amount).trim(),
          reason: typeof reason === 'string' ? reason : null,
        },
      );
      return created[0];
    });
  }

  @Post('/budget-adjustments/:budgetAdjustmentId/close')
  @HttpCode(200)
  async closeBudgetAdjustment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = pathId(req);
    return transaction(async (db) => {
      const row = await loadAdjustment(db, id);
      if (row.status !== '신청') {
        throw new ApiError(409, 'BUDGET_ADJUSTMENT_STATUS_CONFLICT', '신청 상태의 예산조정만 마감할 수 있습니다.');
      }
      await db.execute(
        `UPDATE budget_adjustment SET status = '마감', updated_at = now()
         WHERE budget_adjustment_id = CAST(:id AS bigint)`,
        { id },
      );
      return { status: '마감' };
    });
  }

  @Post('/budget-adjustments/:budgetAdjustmentId/cancel-close')
  @HttpCode(200)
  async cancelCloseBudgetAdjustment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = pathId(req);
    return transaction(async (db) => {
      const row = await loadAdjustment(db, id);
      if (row.status !== '마감') {
        throw new ApiError(409, 'BUDGET_ADJUSTMENT_STATUS_CONFLICT', '마감 상태의 예산조정만 마감취소할 수 있습니다.');
      }
      await db.execute(
        `UPDATE budget_adjustment SET status = '마감취소', updated_at = now()
         WHERE budget_adjustment_id = CAST(:id AS bigint)`,
        { id },
      );
      return { status: '마감취소' };
    });
  }

  @Post('/budget-adjustments/:budgetAdjustmentId/submit-approval')
  @HttpCode(200)
  async submitBudgetAdjustmentApproval(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = pathId(req);
    return transaction(async (db) => {
      const row = await loadAdjustment(db, id);
      if (row.status !== '마감') {
        throw new ApiError(409, 'BUDGET_ADJUSTMENT_NOT_CLOSED', '마감되지 않은 예산조정입니다.');
      }
      if (row.approvalDocumentId !== null && row.approvalDocumentId !== undefined) {
        return {
          approvalDocumentId: Number(row.approvalDocumentId),
          submitResult: '이미 상신되었습니다.',
        };
      }
      // 가정: 전자결재 모듈 상신(S2)을 호출할 수단이 허용 import에 없다.
      // 상신 응답을 받을 수 없으므로 연계 실패로 처리하고 상태는 유지한다.
      throw new ApiError(502, 'APPROVAL_SUBMIT_FAILED', '전자결재 연계에 실패했습니다. 상태는 유지됩니다.');
    });
  }
}

