import { useState } from 'react';
import {
  Badge,
  Band,
  call,
  DataTable,
  DateInput,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  Pager,
  RefName,
  Select,
  Tiles,
  TextInput,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const TYPE_OPTIONS: [string, string][] = [
  ['추경예산', '추경예산'],
  ['전용', '전용'],
  ['이용', '이용'],
  ['예비비', '예비비'],
];

const ACTIONS: Record<string, { label: string; message: string; danger?: boolean }> = {
  'close': { label: '마감', message: '마감했습니다.' },
  'cancel-close': { label: '마감취소', message: '마감을 취소했습니다.', danger: true },
  'submit-approval': { label: '전자결재 상신', message: '전자결재로 상신했습니다.' },
};

const PAGE_SIZE = 20;

export default function FnSfr00304Page({ role, notify }: PageProps) {
  const [projectId, setProjectId] = useState<number | string>('');
  const [budgetItemId, setBudgetItemId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [pageNo, setPageNo] = useState(0);
  const [creating, setCreating] = useState(false);
  const [form, setForm] = useState<Row>({});
  const [act, setAct] = useState<{ kind: string; row: Row } | null>(null);
  const [done, setDone] = useState<Row[]>([]);

  const list = useData<Page<Row>>(
    () =>
      call<Page<Row>>('GET', '/budget-items/execution-balances', role, undefined, {
        ...applied,
        page: pageNo,
        size: PAGE_SIZE,
      }),
    [applied, pageNo, role],
  );

  function setField(key: string, value: unknown) {
    setForm((prev) => ({ ...prev, [key]: value }));
  }

  function search() {
    setPageNo(0);
    setApplied({ projectId, budgetItemId });
  }

  function reset() {
    setProjectId('');
    setBudgetItemId('');
    setPageNo(0);
    setApplied({});
  }

  function openCreate() {
    setForm({});
    setCreating(true);
  }

  async function create() {
    const missing: string[] = [];
    if (!form.adjustmentType) missing.push('예산조정 구분');
    if (!form.budgetItemId) missing.push('대상 예산과목');
    if (!form.projectId) missing.push('프로젝트');
    if (form.amount === undefined || form.amount === '') missing.push('조정 금액');
    if (missing.length > 0) {
      throw new Error('다음 항목을 입력해 주세요: ' + missing.join(', '));
    }
    const res = await call('POST', '/budget-adjustments', role, {
      adjustmentType: form.adjustmentType,
      budgetItemId: form.budgetItemId,
      projectId: form.projectId,
      amount: form.amount,
      reason: form.reason ? form.reason : undefined,
    });
    setDone((prev) => [
      {
        budgetAdjustmentId: res.budgetAdjustmentId,
        status: res.status,
        adjustmentType: form.adjustmentType,
        budgetItemId: form.budgetItemId,
        projectId: form.projectId,
        amount: form.amount,
      },
      ...prev,
    ]);
    notify('예산조정을 신청했습니다.');
    setCreating(false);
    list.reload();
  }

  async function runAction() {
    if (!act) return;
    const id = act.row.budgetAdjustmentId;
    const res = await call('POST', '/budget-adjustments/' + id + '/' + act.kind, role, {});
    setDone((prev) =>
      prev.map((r) =>
        r.budgetAdjustmentId === id
          ? {
              ...r,
              status: res.status ?? r.status,
              approvalDocumentId: res.approvalDocumentId ?? r.approvalDocumentId,
            }
          : r,
      ),
    );
    notify(ACTIONS[act.kind].message);
    setAct(null);
    list.reload();
  }

  const countOf = (status: string) => done.filter((r) => r.status === status).length;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>현황</h2>
        <Tiles
          items={[
            ['예산과목', list.data ? list.data.total : 0],
            ['신청', countOf('신청')],
            ['마감', countOf('마감')],
            ['마감취소', countOf('마감취소')],
          ]}
        />
      </section>

      <section className="box span-8">
        <h2>집행액·예산잔액</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="프로젝트 ID">
            <LookupSelect table="project" role={role} value={projectId} onChange={setProjectId} />
          </Field>
          <Field label="예산과목 ID">
            <LookupSelect table="budget_item" role={role} value={budgetItemId} onChange={setBudgetItemId} />
          </Field>
        </Filters>
        <Band total={list.data ? list.data.total : 0}>
          <button type="button" onClick={openCreate}>예산조정 신청</button>
        </Band>
        {list.error ? <p>{list.error}</p> : null}
        <DataTable
          rows={list.data ? list.data.items : []}
          empty="조회된 예산과목이 없습니다."
          columns={[
            { key: 'itemName', label: '예산과목 명칭' },
            { key: 'executedAmount', label: '집행액', render: (r) => <Num value={r.executedAmount} /> },
            { key: 'balanceAmount', label: '예산잔액', render: (r) => <Num value={r.balanceAmount} /> },
          ]}
        />
        <Pager
          page={pageNo}
          size={PAGE_SIZE}
          total={list.data ? list.data.total : 0}
          onPage={setPageNo}
        />
      </section>

      <section className="box span-4">
        <h2>처리 내역</h2>
        <DataTable
          rows={done}
          empty="이 화면에서 처리한 예산조정이 없습니다."
          columns={[
            { key: 'adjustmentType', label: '구분' },
            { key: 'budgetItemId', label: '예산과목', render: (r) => <RefName table="budget_item" role={role} value={r.budgetItemId} /> },
            { key: 'amount', label: '금액', render: (r) => <Num value={r.amount} /> },
            { key: 'status', label: '상태', render: (r) => <Badge value={r.status} /> },
            {
              key: 'actions',
              label: '처리',
              render: (r) => (
                <span>
                  {r.status === '신청' ? (
                    <button type="button" onClick={() => setAct({ kind: 'close', row: r })}>마감</button>
                  ) : null}
                  {r.status === '마감' ? (
                    <button type="button" onClick={() => setAct({ kind: 'cancel-close', row: r })}>마감취소</button>
                  ) : null}
                  {r.status === '마감' ? (
                    <button type="button" onClick={() => setAct({ kind: 'submit-approval', row: r })}>상신</button>
                  ) : null}
                </span>
              ),
            },
          ]}
        />
      </section>

      {creating ? (
        <Drawer title="예산조정 신청" onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit="신청">
            <Field label="예산조정 구분" required>
              <Select
                value={form.adjustmentType}
                onChange={(v) => setField('adjustmentType', v)}
                options={TYPE_OPTIONS}
              />
            </Field>
            <Field label="대상 예산과목 ID" required>
              <LookupSelect
                table="budget_item"
                role={role}
                value={form.budgetItemId}
                onChange={(v) => setField('budgetItemId', v)}
              />
            </Field>
            <Field label="프로젝트 ID" required>
              <LookupSelect
                table="project"
                role={role}
                value={form.projectId}
                onChange={(v) => setField('projectId', v)}
              />
            </Field>
            <Field label="조정 금액" required hint="전용·이용은 예산잔액을 넘을 수 없습니다.">
              <NumberInput value={form.amount} onChange={(v) => setField('amount', v)} />
            </Field>
            <Field label="조정 사유" wide>
              <TextInput
                multiline
                value={form.reason}
                onChange={(v) => setField('reason', v)}
              />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {act ? (
        <Drawer title={ACTIONS[act.kind].label} onClose={() => setAct(null)}>
          <Form
            onSubmit={runAction}
            submit={ACTIONS[act.kind].label}
            danger={ACTIONS[act.kind].danger}
            note={'예산조정 ' + String(act.row.budgetAdjustmentId) + '번을 ' + ACTIONS[act.kind].label + '합니다.'}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
